INSERT INTO notices(member_id,notice_type,title,content,is_pinned,deleted_at,created_at,updated_at) VALUES
(3,'GENERAL','고객센터 운영시간 안내','고객센터는 평일 10:00~17:00(점심 12:00~13:00)에 운영하며 주말·공휴일은 휴무입니다. 게시판 문의는 영업일 기준 1~2일 내 답변드립니다.',false,NULL,'2023-11-22 14:05:26','2023-11-22 14:05:26'),
(1,'EVENT','신규 회원 가입 쿠폰 지급 이벤트','신규 가입 고객님께 첫 구매 3,000원 할인 쿠폰을 드립니다. 가입 후 마이페이지 쿠폰함에서 확인하세요.',false,NULL,'2023-12-01 11:15:44','2023-12-01 11:15:44'),
(1,'GENERAL','이용약관 개정 안내','서비스 이용약관 일부가 개정되었습니다. 개정 내용은 공지일로부터 7일 후 적용되며 자세한 내용은 약관 페이지에서 확인하실 수 있습니다.',false,NULL,'2023-12-04 15:06:46','2023-12-04 15:06:46'),
(3,'GENERAL','택배사 변경 및 배송 안내','배송 품질 향상을 위해 일부 지역의 택배사가 변경되었습니다. 도서산간 지역은 추가 배송일이 소요될 수 있습니다.',false,NULL,'2024-01-08 15:30:27','2024-01-08 15:30:27'),
(1,'EVENT','우리 아이 첫 구매 감사 이벤트','첫 구매 고객님께 샘플 간식을 함께 보내드립니다. 소진 시까지 진행됩니다.',false,NULL,'2024-02-14 15:52:01','2024-02-14 15:52:01'),
(1,'GENERAL','2월 정기 시스템 점검 안내','더 안정적인 서비스를 위해 2월 19일 새벽 2시부터 4시까지 정기 점검이 진행됩니다. 점검 시간 동안 주문과 결제, 로그인이 일시 제한됩니다.',false,NULL,'2024-02-16 14:17:54','2024-02-16 14:17:54'),
(3,'GENERAL','무료배송 기준 안내','5만원 이상 구매 시 무료배송이며, 미만 시 배송비 3,000원이 부과됩니다. 제주·도서산간은 추가 배송비가 있을 수 있습니다.',false,NULL,'2024-03-12 10:34:49','2024-03-12 10:34:49'),
(1,'EVENT','봄맞이 산책용품 기획전','봄철 산책을 위한 하네스, 급수용품, 배변용품을 모았습니다. 기획전 상품 구매 시 사은품을 드립니다. 수량 소진 시 종료됩니다.',false,NULL,'2024-04-01 11:37:20','2024-04-01 11:37:20'),
(1,'GENERAL','간편결제 수단 추가 안내','카드, 간편결제에 더해 계좌이체와 가상계좌 결제가 가능합니다. 결제 수단은 주문 단계에서 선택하실 수 있습니다.',false,NULL,'2024-04-02 09:50:06','2024-04-02 09:50:06'),
(3,'EVENT','친구 초대 이벤트','친구를 초대하면 초대한 분과 가입한 분 모두에게 적립금을 드립니다. 마이페이지에서 초대 링크를 확인하세요.',false,NULL,'2024-04-08 11:04:06','2024-04-08 11:04:06'),
(1,'GENERAL','신규 브랜드 입점 안내','이번 달 새로 입점한 브랜드 상품을 만나보세요. 입점 상품은 신상품 카테고리에서 확인하실 수 있습니다.',false,NULL,'2024-05-20 14:44:03','2024-05-20 14:44:03'),
(1,'EVENT','6월 반려동물 건강검진 캠페인','반려동물 건강검진 인증 사진을 남겨주시면 추첨을 통해 영양제를 드립니다.',false,NULL,'2024-06-03 09:24:06','2024-06-03 09:24:06'),
(3,'GENERAL','6월 정기 시스템 점검 안내','더 안정적인 서비스를 위해 6월 15일 새벽 2시부터 4시까지 정기 점검이 진행됩니다. 점검 시간 동안 주문과 결제, 로그인이 일시 제한됩니다.',false,NULL,'2024-06-12 14:44:45','2024-06-12 14:44:45'),
(1,'GENERAL','여름철 사료 보관 방법 안내','고온다습한 여름에는 개봉한 사료를 서늘한 곳에 밀봉해 보관해 주세요. 개봉 후 4주 이내 급여를 권장합니다.',false,NULL,'2024-07-04 16:23:56','2024-07-04 16:23:56'),
(1,'EVENT','여름 휴가 펫시터 용품 특가','휴가철 외출 필수 용품을 특가로 만나보세요. 이동가방, 휴대용 급수기, 배변패드가 포함됩니다.',false,NULL,'2024-07-15 09:32:14','2024-07-15 09:32:14'),
(3,'GENERAL','개인정보 처리방침 개정 안내','개인정보 처리방침이 일부 개정되었습니다. 변경 사항은 하단 링크에서 확인해 주세요.',false,NULL,'2024-08-26 10:02:25','2024-08-26 10:02:25'),
(1,'EVENT','가을맞이 산책용품 기획전','가을철 산책을 위한 하네스, 급수용품, 배변용품을 모았습니다. 기획전 상품 구매 시 사은품을 드립니다. 수량 소진 시 종료됩니다.',false,NULL,'2024-09-01 11:38:08','2024-09-01 11:38:08'),
(1,'GENERAL','품절 상품 재입고 알림 서비스 안내','품절 상품은 재입고 알림을 신청해 주시면 입고 시 알려드립니다. 상품 상세 페이지에서 신청하세요.',false,NULL,'2024-09-30 15:38:06','2024-09-30 15:38:06'),
(3,'EVENT','10월 가을맞이 사료 교체 기획전','환절기 사료 교체 시기에 맞춰 소포장 체험팩을 준비했습니다.',false,NULL,'2024-10-01 14:11:34','2024-10-01 14:11:34'),
(1,'GENERAL','10월 정기 시스템 점검 안내','더 안정적인 서비스를 위해 10월 8일 새벽 2시부터 4시까지 정기 점검이 진행됩니다. 점검 시간 동안 주문과 결제, 로그인이 일시 제한됩니다.',false,NULL,'2024-10-05 14:52:38','2024-10-05 14:52:38'),
(1,'GENERAL','겨울철 배송 지연 가능성 안내','한파와 폭설로 일부 지역의 배송이 지연될 수 있습니다. 양해 부탁드립니다.',false,NULL,'2024-11-05 14:14:44','2024-11-05 14:14:44'),
(3,'EVENT','사이버먼데이 추가 할인','블랙프라이데이에 이어 사이버먼데이에도 추가 할인을 진행합니다. 단, 재고 소진 시 조기 종료됩니다.',false,NULL,'2024-12-02 09:19:05','2024-12-02 09:19:05'),
(1,'GENERAL','연말 고객센터 휴무 안내','12월 31일과 1월 1일은 고객센터가 휴무입니다. 휴무 기간 중 접수된 문의는 1월 2일부터 순차적으로 답변드립니다.',false,NULL,'2024-12-26 10:16:48','2024-12-26 10:16:48'),
(1,'GENERAL','교환/반품 절차 안내','수령 후 7일 이내 교환·반품이 가능합니다. 단, 개봉한 식품과 사용한 용품은 교환이 제한될 수 있습니다.',false,NULL,'2025-01-14 09:48:24','2025-01-14 09:48:24'),
(3,'EVENT','설맞이 반려동물 간식 선물 이벤트','설 선물용 간식 세트를 구매하시면 포장 서비스를 무료로 제공합니다.',false,NULL,'2025-01-20 16:20:57','2025-01-20 16:20:57'),
(1,'GENERAL','2월 정기 시스템 점검 안내','더 안정적인 서비스를 위해 2월 15일 새벽 2시부터 4시까지 정기 점검이 진행됩니다. 점검 시간 동안 주문과 결제, 로그인이 일시 제한됩니다.',false,NULL,'2025-02-12 11:23:47','2025-02-12 11:23:47'),
(1,'GENERAL','회원 등급 및 적립금 정책 안내','구매 금액에 따라 적립금이 쌓이며, 적립금은 다음 주문 시 사용하실 수 있습니다. 유효기간은 적립일로부터 1년입니다.',false,NULL,'2025-02-18 09:38:45','2025-02-18 09:38:45'),
(3,'EVENT','봄 맞이 털갈이 케어 기획전','털갈이 시즌 필수 브러시와 모질 케어 영양제를 모았습니다.',false,NULL,'2025-02-24 14:25:00','2025-02-24 14:25:00'),
(1,'GENERAL','3월 14일 서비스 장애 보상 안내','3월 14일 서비스 장애로 불편을 겪으신 고객님께 사과드리며, 해당 시간대 주문 고객님께 보상 쿠폰을 지급했습니다.',false,NULL,'2025-03-18 15:38:42','2025-03-18 15:38:42'),
(1,'EVENT','봄맞이 산책용품 기획전','봄철 산책을 위한 하네스, 급수용품, 배변용품을 모았습니다. 기획전 상품 구매 시 사은품을 드립니다. 수량 소진 시 종료됩니다.',false,NULL,'2025-04-01 11:17:50','2025-04-01 11:17:50'),
(3,'GENERAL','주문량 증가에 따른 배송 안내','주문이 늘어 출고가 평소보다 1~2일 지연되고 있습니다. 빠르게 정상화하겠습니다.',false,NULL,'2025-04-19 14:14:26','2025-04-19 14:14:26'),
(1,'EVENT','어린이날·어버이날 반려가족 이벤트','가족과 함께하는 반려 라이프 사진을 남겨 주시면 추첨을 통해 적립금을 드립니다.',false,NULL,'2025-05-12 10:10:12','2025-05-12 10:10:12'),
(1,'GENERAL','반려동물 정보 등록 기능 업데이트','마이페이지에서 반려동물 정보를 등록하면 맞춤 상품 추천을 받아보실 수 있습니다. 알러지 정보도 입력하실 수 있어요.',false,NULL,'2025-05-27 09:07:26','2025-05-27 09:07:26'),
(3,'GENERAL','6월 정기 시스템 점검 안내','더 안정적인 서비스를 위해 6월 8일 새벽 2시부터 4시까지 정기 점검이 진행됩니다. 점검 시간 동안 주문과 결제, 로그인이 일시 제한됩니다.',false,NULL,'2025-06-05 10:07:22','2025-06-05 10:07:22'),
(1,'EVENT','장마철 습기 제거 용품 기획전','습한 날씨에 대비한 사료 보관통과 탈취 용품을 특가로 준비했습니다.',false,NULL,'2025-06-16 14:06:14','2025-06-16 14:06:14'),
(1,'GENERAL','자동 급수기 일부 모델 점검 안내','일부 자동 급수기 모델에서 펌프 소음과 누수 문의가 접수되어 원인을 확인하고 있습니다. 해당 모델 구매 고객님께는 개별 안내드립니다.',false,NULL,'2025-07-09 09:22:19','2025-07-09 09:22:19'),
(3,'EVENT','여름 쿨링 용품 추가 할인','쿨매트, 급수기, 휴대용 물병을 추가 할인합니다. 한정 수량입니다.',false,NULL,'2025-08-04 09:07:24','2025-08-04 09:07:24'),
(1,'GENERAL','급수기 문의 처리 현황 안내','급수기 관련 접수 건은 교환·환불을 우선 처리 중입니다. 고객센터로 주문번호와 증상을 알려주세요.',false,NULL,'2025-08-14 09:30:42','2025-08-14 09:30:42'),
(1,'EVENT','가을맞이 산책용품 기획전','가을철 산책을 위한 하네스, 급수용품, 배변용품을 모았습니다. 기획전 상품 구매 시 사은품을 드립니다. 수량 소진 시 종료됩니다.',false,NULL,'2025-09-01 09:17:37','2025-09-01 09:17:37'),
(3,'GENERAL','추석 연휴 주문·배송 일정 안내','추석 연휴 전 배송은 주문 마감일까지 접수된 건에 한해 진행됩니다. 연휴 중 주문은 연휴 이후 순차 출고됩니다.',false,NULL,'2025-09-03 10:35:00','2025-09-03 10:35:00'),
(1,'GENERAL','10월 정기 시스템 점검 안내','더 안정적인 서비스를 위해 10월 8일 새벽 2시부터 4시까지 정기 점검이 진행됩니다. 점검 시간 동안 주문과 결제, 로그인이 일시 제한됩니다.',false,NULL,'2025-10-05 11:08:09','2025-10-05 11:08:09'),
(1,'EVENT','가을 걷기 챌린지','산책 사진을 인증하면 추첨을 통해 간식을 드립니다. 이벤트 기간 동안 응모 가능합니다.',false,NULL,'2025-10-20 11:47:03','2025-10-20 11:47:03'),
(3,'GENERAL','리뷰 작성 가이드 안내','구매하신 상품의 사용 경험을 남겨 주세요. 상품과 무관한 내용이나 광고성 글은 삭제될 수 있습니다.',false,NULL,'2025-11-03 09:01:50','2025-11-03 09:01:50'),
(1,'EVENT','11.11 특가 예고','11월 11일 하루 특가를 진행합니다. 알림을 신청하시면 시작 전에 알려드려요.',false,NULL,'2025-11-10 14:24:33','2025-11-10 14:24:33'),
(1,'EVENT','연말 감사 적립금 이벤트','올해 구매 금액에 따라 감사 적립금을 지급합니다. 적립금은 1월 중 지급됩니다.',false,NULL,'2025-12-08 16:19:35','2025-12-08 16:19:35'),
(3,'GENERAL','연말 택배 대란 대비 배송 안내','연말 물량 증가로 배송이 지연될 수 있어 12월 20일 이전 주문을 권장드립니다.',false,NULL,'2025-12-22 14:14:36','2025-12-22 14:14:36'),
(1,'GENERAL','2026년 달라지는 서비스 안내','새해부터 상품 검색 필터와 정렬 기능이 개선되었습니다. 반려동물 종류와 연령별로 상품을 골라 보세요.',false,NULL,'2026-01-12 14:49:15','2026-01-12 14:49:15'),
(1,'EVENT','설 연휴 전 마감 임박 특가','설 연휴 전 배송을 위한 마지막 특가입니다. 오늘 오후 2시까지 결제 완료 건에 한해 연휴 전 출고됩니다.',false,NULL,'2026-02-02 09:00:15','2026-02-02 09:00:15'),
(3,'GENERAL','2월 정기 시스템 점검 안내','더 안정적인 서비스를 위해 2월 15일 새벽 2시부터 4시까지 정기 점검이 진행됩니다. 점검 시간 동안 주문과 결제, 로그인이 일시 제한됩니다.',false,NULL,'2026-02-12 09:59:07','2026-02-12 09:59:07'),
(1,'GENERAL','비회원 주문 조회 방법 안내','비회원 주문은 주문번호와 연락처로 조회하실 수 있습니다. 회원 가입 시 주문 내역을 더 편하게 관리하실 수 있습니다.',false,NULL,'2026-03-05 11:53:59','2026-03-05 11:53:59'),
(1,'EVENT','리뷰 베스트 선정 이벤트','3월 포토리뷰 중 베스트를 선정해 적립금을 드립니다. 발표는 4월 초 공지사항에 게시됩니다.',false,NULL,'2026-03-24 16:23:00','2026-03-24 16:23:00'),
(3,'EVENT','봄맞이 산책용품 기획전','봄철 산책을 위한 하네스, 급수용품, 배변용품을 모았습니다. 기획전 상품 구매 시 사은품을 드립니다. 수량 소진 시 종료됩니다.',false,NULL,'2026-04-01 14:21:27','2026-04-01 14:21:27'),
(1,'GENERAL','봄철 알러지 케어 상품 안내','환절기에는 피부와 소화기 문제가 늘 수 있습니다. 알러지 케어 상품은 카테고리에서 확인해 주세요.',false,NULL,'2026-04-21 14:49:53','2026-04-21 14:49:53'),
